checkCopyFail() {
    (
        CF31_PY_TIMEOUT=12
        CF31_TMP_PY=""
        trap '[ -n "$CF31_TMP_PY" ] && rm -f "$CF31_TMP_PY"' EXIT HUP INT TERM
        CF31_KERNEL_OS=$(uname -s 2>/dev/null || echo unknown)
        if [ "$CF31_KERNEL_OS" != "Linux" ]; then
            echo "NOT APPLICABLE: Copy Fail (CVE-2026-31431) affects Linux kernels only." | sed -${E} "s,.*,${SED_GREEN},"
            exit 0
        fi
        for CF31_CANDIDATE in python3 python; do
            if command -v "$CF31_CANDIDATE" >/dev/null 2>&1 && cf31_py_can_run_probe "$CF31_CANDIDATE"; then
                CF31_MSG=$(cf31_run_python_probe "$CF31_CANDIDATE")
                CF31_RC=$?
                case "$CF31_RC" in
                    0)
                        printf "%s\n" "$CF31_MSG" | sed -${E} "s,.*,${SED_GREEN},"
                        exit 0
                        ;;
                    2)
                        printf "%s\n" "$CF31_MSG" | sed -${E} "s,.*,${SED_RED_YELLOW},"
                        exit 2
                        ;;
                    1)
                        [ -n "$CF31_MSG" ] && printf "%s\n" "$CF31_MSG" | sed -${E} "s,.*,${SED_RED_YELLOW},"
                        ;;
                esac
                echo "Python probe inconclusive; falling back to POSIX sh triage."
                break
            fi
        done
        CF31_KERNEL_RELEASE=$(uname -r 2>/dev/null || echo unknown)
        CF31_KV=$(printf '%s\n' "$CF31_KERNEL_RELEASE" | sed 's/^[^0-9]*//; s/[^0-9.].*$//')
        CF31_KERNEL_VERSION="$CF31_KV"
        set -- $(printf '%s\n' "$CF31_KV" | tr '.' ' ')
        CF31_MAJ=$(cf31_num "${1:-0}")
        CF31_MIN=$(cf31_num "${2:-0}")
        CF31_PAT=$(cf31_num "${3:-0}")
        CF31_API=unknown
        CF31_CFG=''
        for CF31_CFG_FILE in /proc/config.gz /boot/config-"$CF31_KERNEL_RELEASE" /lib/modules/"$CF31_KERNEL_RELEASE"/config; do
            [ -r "$CF31_CFG_FILE" ] || continue
            case "$CF31_CFG_FILE" in
                *.gz)
                    if command -v gzip >/dev/null 2>&1; then
                        CF31_CFG_LINE=$(gzip -cd "$CF31_CFG_FILE" 2>/dev/null | grep -E '^(# )?CONFIG_CRYPTO_USER_API_AEAD(=| is not set)' | tail -n 1)
                    else
                        CF31_CFG_LINE=''
                    fi
                    ;;
                *)
                    CF31_CFG_LINE=$(grep -E '^(# )?CONFIG_CRYPTO_USER_API_AEAD(=| is not set)' "$CF31_CFG_FILE" 2>/dev/null | tail -n 1)
                    ;;
            esac
            [ -n "$CF31_CFG_LINE" ] && CF31_CFG=$CF31_CFG_LINE
        done
        case "$CF31_CFG" in
            *'is not set'*) CF31_API=off ;;
            *=y) CF31_API=builtin ;;
            *=m) CF31_API=module ;;
        esac
        if [ "$CF31_API" = unknown ]; then
            if [ -e /sys/module/algif_aead ]; then
                CF31_API=loaded
            elif command -v modinfo >/dev/null 2>&1 && modinfo algif_aead >/dev/null 2>&1; then
                CF31_API=module
            elif find /lib/modules/"$CF31_KERNEL_RELEASE" -name 'algif_aead.ko*' -print 2>/dev/null | grep -q .; then
                CF31_API=module
            elif [ -r /proc/crypto ] && grep -q 'authencesn(hmac(sha256),cbc(aes))' /proc/crypto 2>/dev/null; then
                CF31_API=reachable
            fi
        fi
        if [ "$CF31_API" = off ]; then
            echo "NOT VULNERABLE: CONFIG_CRYPTO_USER_API_AEAD is disabled." | sed -${E} "s,.*,${SED_GREEN},"
            exit 0
        fi
        CF31_BLOCKED=no
        for CF31_CFG_FILE in /etc/modprobe.d/*.conf /lib/modprobe.d/*.conf /usr/lib/modprobe.d/*.conf; do
            [ -f "$CF31_CFG_FILE" ] || continue
            if grep -Eq '^[[:space:]]*install[[:space:]]+algif_aead[[:space:]]+(/usr)?/bin/(false|true)([[:space:]]|$)' "$CF31_CFG_FILE" 2>/dev/null; then
                CF31_BLOCKED=yes
            fi
        done
        if [ "$CF31_API" = module ] && [ "$CF31_BLOCKED" = yes ] && [ ! -e /sys/module/algif_aead ]; then
            echo "NOT VULNERABLE: algif_aead autoload is blocked and the module is not loaded." | sed -${E} "s,.*,${SED_GREEN},"
            exit 0
        fi
        if [ -r /proc/cmdline ] && grep -q 'initcall_blacklist=algif_aead_init' /proc/cmdline 2>/dev/null; then
            echo "LIKELY NOT VULNERABLE: kernel booted with initcall_blacklist=algif_aead_init." | sed -${E} "s,.*,${SED_GREEN},"
            exit 0
        fi
        CF31_FIXED_PKG=no
        if command -v dpkg-query >/dev/null 2>&1; then
            CF31_PKG=$(dpkg-query -S "/boot/vmlinuz-$CF31_KERNEL_RELEASE" 2>/dev/null | sed 's/:.*//' | sed -n '1p')
            if [ -n "$CF31_PKG" ]; then
                for CF31_CFG_FILE in /usr/share/doc/"$CF31_PKG"/changelog*; do
                    [ -f "$CF31_CFG_FILE" ] || continue
                    case "$CF31_CFG_FILE" in
                        *.gz) command -v gzip >/dev/null 2>&1 && gzip -cd "$CF31_CFG_FILE" 2>/dev/null ;;
                        *) cat "$CF31_CFG_FILE" 2>/dev/null ;;
                    esac
                done | grep -Eiq 'CVE-2026-31431|a664bf3d603d|ce42ee423e58|fafe0fa2995a|algif_aead.*out-of-place|Revert to operating out-of-place' && CF31_FIXED_PKG=yes
            fi
        fi
        if [ "$CF31_FIXED_PKG" = no ] && command -v rpm >/dev/null 2>&1; then
            CF31_PKG=$(rpm -q --whatprovides "kernel-uname-r = $CF31_KERNEL_RELEASE" 2>/dev/null | sed -n '1p')
            case "$CF31_PKG" in
                ''|no\ package*) ;;
                *)
                    rpm -q --changelog "$CF31_PKG" 2>/dev/null |
                        grep -Eiq 'CVE-2026-31431|a664bf3d603d|ce42ee423e58|fafe0fa2995a|algif_aead.*out-of-place|Revert to operating out-of-place' && CF31_FIXED_PKG=yes
                    ;;
            esac
        fi
        if [ "$CF31_FIXED_PKG" = yes ]; then
            echo "LIKELY NOT VULNERABLE: running kernel package changelog mentions the CVE-2026-31431 fix." | sed -${E} "s,.*,${SED_GREEN},"
            exit 0
        fi
        if [ "$CF31_MAJ" -lt 4 ] || { [ "$CF31_MAJ" -eq 4 ] && [ "$CF31_MIN" -lt 14 ]; }; then
            echo "NOT VULNERABLE for upstream kernel version: $CF31_KERNEL_RELEASE predates the vulnerable upstream commit." | sed -${E} "s,.*,${SED_GREEN},"
            exit 0
        fi
        if cf31_is_fixed_upstream_release; then
            echo "LIKELY NOT VULNERABLE for upstream kernel version: $CF31_KERNEL_RELEASE is at/after a fixed upstream release." | sed -${E} "s,.*,${SED_GREEN},"
            exit 0
        fi
        if [ "$CF31_API" = unknown ]; then
            echo "UNKNOWN: $CF31_KERNEL_RELEASE is in the affected upstream range, but AEAD user API exposure could not be verified." | sed -${E} "s,.*,${SED_RED_YELLOW},"
            exit 1
        fi
        echo "LIKELY VULNERABLE: $CF31_KERNEL_RELEASE is in the affected upstream range and AEAD user API appears $CF31_API." | sed -${E} "s,.*,${SED_RED_YELLOW},"
        exit 2
    )
}

KERNEL_CVE_EXPL=""
KERNEL_CVE_ALT=""
KERNEL_CVE_MIL=""
kercve_norm_ver() {
    printf "%s" "$1" | tr '-' '.' | sed 's/[^0-9.].*$//' | sed 's/\.\./\./g' | sed 's/^\.//' | sed 's/\.$//'
}
kercve_ver_cmp() {
    KERNEL_CVE_CURVER=$(kercve_norm_ver "$1")
    KERNEL_CVE_REQVER=$(kercve_norm_ver "$3")
    KERNEL_CVE_OP="$2"
    [ -z "$KERNEL_CVE_CURVER" ] && return 1
    [ -z "$KERNEL_CVE_REQVER" ] && return 1
    KERNEL_CVE_CMP=$(awk -v a="$KERNEL_CVE_CURVER" -v b="$KERNEL_CVE_REQVER" '
    function clean(v){gsub(/[^0-9]/,"",v); if(v=="")v=0; return v+0}
    BEGIN{
      na=split(a,A,"."); nb=split(b,B,"."); n=(na>nb?na:nb);
      for(i=1;i<=n;i++){
        va=(i<=na?clean(A[i]):0); vb=(i<=nb?clean(B[i]):0);
        if(va<vb){print -1; exit}
        if(va>vb){print 1; exit}
      }
      print 0
    }')
    case "$KERNEL_CVE_OP" in
        '=') [ "$KERNEL_CVE_CMP" -eq 0 ] ;;
        '>') [ "$KERNEL_CVE_CMP" -gt 0 ] ;;
        '<') [ "$KERNEL_CVE_CMP" -lt 0 ] ;;
        '>=') [ "$KERNEL_CVE_CMP" -ge 0 ] ;;
        '<=') [ "$KERNEL_CVE_CMP" -le 0 ] ;;
        *) return 1 ;;
    esac
}
kercve_get_cfg_line() {
    KERNEL_CVE_CFG_KEY="$1"
    if [ -z "$KERNEL_CVE_CFG_SOURCE" ] || ! [ -r "$KERNEL_CVE_CFG_SOURCE" ]; then
        return 1
    fi
    if printf "%s" "$KERNEL_CVE_CFG_SOURCE" | grep -q '\\.gz$'; then
        KERNEL_CVE_CFG_LINE=$(gzip -dc "$KERNEL_CVE_CFG_SOURCE" 2>/dev/null | grep -E "^(${KERNEL_CVE_CFG_KEY}=|# ${KERNEL_CVE_CFG_KEY} is not set)" | head -n1)
    else
        KERNEL_CVE_CFG_LINE=$(grep -E "^(${KERNEL_CVE_CFG_KEY}=|# ${KERNEL_CVE_CFG_KEY} is not set)" "$KERNEL_CVE_CFG_SOURCE" 2>/dev/null | head -n1)
    fi
    [ -n "$KERNEL_CVE_CFG_LINE" ]
}
kercve_eval_config_req() {
    KERNEL_CVE_CFG_EXPR="$1"
    [ -z "$KERNEL_CVE_CFG_SOURCE" ] && return 0
    if printf "%s" "$KERNEL_CVE_CFG_EXPR" | grep -q '!='; then
        KERNEL_CVE_CFG_OP='!='
        KERNEL_CVE_CFG_KEY=$(printf "%s" "$KERNEL_CVE_CFG_EXPR" | awk -F'!=' '{print $1}')
        KERNEL_CVE_CFG_EXPECT=$(printf "%s" "$KERNEL_CVE_CFG_EXPR" | awk -F'!=' '{print $2}')
    elif printf "%s" "$KERNEL_CVE_CFG_EXPR" | grep -q '='; then
        KERNEL_CVE_CFG_OP='='
        KERNEL_CVE_CFG_KEY=$(printf "%s" "$KERNEL_CVE_CFG_EXPR" | awk -F'=' '{print $1}')
        KERNEL_CVE_CFG_EXPECT=$(printf "%s" "$KERNEL_CVE_CFG_EXPR" | awk -F'=' '{print $2}')
    else
        KERNEL_CVE_CFG_OP='present'
        KERNEL_CVE_CFG_KEY="$KERNEL_CVE_CFG_EXPR"
        KERNEL_CVE_CFG_EXPECT='[my]'
    fi
    if ! kercve_get_cfg_line "$KERNEL_CVE_CFG_KEY"; then
        return 0
    fi
    if printf "%s" "$KERNEL_CVE_CFG_LINE" | grep -q '# .* is not set'; then
        KERNEL_CVE_CFG_CUR='n'
    else
        KERNEL_CVE_CFG_CUR=$(printf "%s" "$KERNEL_CVE_CFG_LINE" | awk -F'=' '{print $2}')
    fi
    if [ "$KERNEL_CVE_CFG_OP" = '!=' ]; then
        if printf "%s" "$KERNEL_CVE_CFG_EXPECT" | grep -q '\\[my\\]'; then
            ! printf "%s" "$KERNEL_CVE_CFG_CUR" | grep -Eq '^[my]$'
        else
            [ "$KERNEL_CVE_CFG_CUR" != "$KERNEL_CVE_CFG_EXPECT" ]
        fi
        return
    fi
    if printf "%s" "$KERNEL_CVE_CFG_EXPECT" | grep -q '\\[my\\]'; then
        printf "%s" "$KERNEL_CVE_CFG_CUR" | grep -Eq '^[my]$'
        return
    fi
    [ "$KERNEL_CVE_CFG_CUR" = "$KERNEL_CVE_CFG_EXPECT" ]
}
kercve_eval_sysctl_req() {
    KERNEL_CVE_SYS_EXPR="$1"
    if printf "%s" "$KERNEL_CVE_SYS_EXPR" | grep -q '!='; then
        KERNEL_CVE_SYS_OP='!='
        KERNEL_CVE_SYS_KEY=$(printf "%s" "$KERNEL_CVE_SYS_EXPR" | awk -F'!=' '{print $1}')
        KERNEL_CVE_SYS_VAL=$(printf "%s" "$KERNEL_CVE_SYS_EXPR" | awk -F'!=' '{print $2}')
    elif printf "%s" "$KERNEL_CVE_SYS_EXPR" | grep -q '=='; then
        KERNEL_CVE_SYS_OP='=='
        KERNEL_CVE_SYS_KEY=$(printf "%s" "$KERNEL_CVE_SYS_EXPR" | awk -F'==' '{print $1}')
        KERNEL_CVE_SYS_VAL=$(printf "%s" "$KERNEL_CVE_SYS_EXPR" | awk -F'==' '{print $2}')
    else
        return 1
    fi
    KERNEL_CVE_SYS_CUR=$(sysctl -n "$KERNEL_CVE_SYS_KEY" 2>/dev/null)
    [ -z "$KERNEL_CVE_SYS_CUR" ] && return 0
    if [ "$KERNEL_CVE_SYS_OP" = '==' ]; then
        [ "$KERNEL_CVE_SYS_CUR" = "$KERNEL_CVE_SYS_VAL" ]
    else
        [ "$KERNEL_CVE_SYS_CUR" != "$KERNEL_CVE_SYS_VAL" ]
    fi
}
kercve_eval_req_token() {
    KERNEL_CVE_REQ="$1"
    [ -z "$KERNEL_CVE_REQ" ] && return 0
    if printf "%s" "$KERNEL_CVE_REQ" | grep -q '^pkg='; then
        [ "$KERNEL_CVE_REQ" = 'pkg=linux-kernel' ]
        return
    fi
    if printf "%s" "$KERNEL_CVE_REQ" | grep -q '^ver'; then
        KERNEL_CVE_OP=$(printf "%s" "$KERNEL_CVE_REQ" | sed -E 's/^ver(<=|>=|=|<|>).*/\1/')
        KERNEL_CVE_VER=$(printf "%s" "$KERNEL_CVE_REQ" | sed -E 's/^ver(<=|>=|=|<|>)//')
        kercve_ver_cmp "$KERNEL_CVE_KERNEL_VERSION" "$KERNEL_CVE_OP" "$KERNEL_CVE_VER"
        return
    fi
    if [ "$KERNEL_CVE_REQ" = 'x86_64' ]; then
        [ "$KERNEL_CVE_KERNEL_ARCH" = 'x86_64' ]
        return
    fi
    if [ "$KERNEL_CVE_REQ" = 'x86' ]; then
        [ "$KERNEL_CVE_KERNEL_ARCH" = 'i386' ] || [ "$KERNEL_CVE_KERNEL_ARCH" = 'i686' ] || [ "$KERNEL_CVE_KERNEL_ARCH" = 'x86' ]
        return
    fi
    if printf "%s" "$KERNEL_CVE_REQ" | grep -q '^CONFIG_'; then
        kercve_eval_config_req "$KERNEL_CVE_REQ"
        return
    fi
    if printf "%s" "$KERNEL_CVE_REQ" | grep -q '^sysctl:'; then
        kercve_eval_sysctl_req "${KERNEL_CVE_REQ#sysctl:}"
        return
    fi
    if printf "%s" "$KERNEL_CVE_REQ" | grep -q '^cmd:'; then
        eval "${KERNEL_CVE_REQ#cmd:}" >/dev/null 2>&1
        return
    fi
    return 1
}
kercve_match_version_list() {
    KERNEL_CVE_VERS="$1"
    KERNEL_CVE_VER_LINES=$(printf "%s" "$KERNEL_CVE_VERS" | tr ',' '\n')
    while IFS= read -r KERNEL_CVE_VER; do
        KERNEL_CVE_VER=$(printf "%s" "$KERNEL_CVE_VER" | sed 's/^ *//;s/ *$//')
        [ -z "$KERNEL_CVE_VER" ] && continue
        if printf "%s" "$KERNEL_CVE_KERNEL_VERSION" | grep -Eq "^${KERNEL_CVE_VER}(\\.|-|$)"; then
            return 0
        fi
    done <<EOFV
$KERNEL_CVE_VER_LINES
EOFV
    return 1
}
kercve_normalize_cve_list() {
    KERNEL_CVE_ID_RAW="$1"
    KERNEL_CVE_ID_OUT=""
    KERNEL_CVE_ID_RAW=$(printf "%s" "$KERNEL_CVE_ID_RAW" | tr ';' ',' | tr '|' ',')
    while IFS= read -r KERNEL_CVE_ID_ITEM; do
        KERNEL_CVE_ID_ITEM=$(printf "%s" "$KERNEL_CVE_ID_ITEM" | sed 's/^ *//;s/ *$//' | tr '[:lower:]' '[:upper:]')
        [ -z "$KERNEL_CVE_ID_ITEM" ] && continue
        if printf "%s" "$KERNEL_CVE_ID_ITEM" | grep -Eq '^CVE-[0-9]{4}-[0-9]+$'; then
            if [ -z "$KERNEL_CVE_ID_OUT" ]; then KERNEL_CVE_ID_OUT="$KERNEL_CVE_ID_ITEM"; else KERNEL_CVE_ID_OUT="$KERNEL_CVE_ID_OUT,$KERNEL_CVE_ID_ITEM"; fi
            continue
        fi
        if printf "%s" "$KERNEL_CVE_ID_ITEM" | grep -Eq '^[0-9]{4}-[0-9]+$'; then
            if [ -z "$KERNEL_CVE_ID_OUT" ]; then KERNEL_CVE_ID_OUT="CVE-$KERNEL_CVE_ID_ITEM"; else KERNEL_CVE_ID_OUT="$KERNEL_CVE_ID_OUT,CVE-$KERNEL_CVE_ID_ITEM"; fi
            continue
        fi
    done <<EOFC
$(printf "%s" "$KERNEL_CVE_ID_RAW" | tr ',' '\n')
EOFC
    printf "%s" "$KERNEL_CVE_ID_OUT"
}
kercve_print_match() {
    KERNEL_CVE_PRINT_ID="$1"
    KERNEL_CVE_NAME="$2"
    KERNEL_CVE_REQS="$3"
    KERNEL_CVE_TAGS="$4"
    KERNEL_CVE_RANK="$5"
    KERNEL_CVE_COMMENTS="$6"
    KERNEL_CVE_PRINT_LINE=""
    [ -n "$KERNEL_CVE_PRINT_ID" ] && KERNEL_CVE_PRINT_LINE="CVE: $KERNEL_CVE_PRINT_ID"
    [ -n "$KERNEL_CVE_NAME" ] && KERNEL_CVE_PRINT_LINE="${KERNEL_CVE_PRINT_LINE}${KERNEL_CVE_PRINT_LINE:+ | }Name: $KERNEL_CVE_NAME"
    [ -n "$KERNEL_CVE_REQS" ] && KERNEL_CVE_PRINT_LINE="${KERNEL_CVE_PRINT_LINE}${KERNEL_CVE_PRINT_LINE:+ | }Match data: $KERNEL_CVE_REQS"
    [ -n "$KERNEL_CVE_TAGS" ] && KERNEL_CVE_PRINT_LINE="${KERNEL_CVE_PRINT_LINE}${KERNEL_CVE_PRINT_LINE:+ | }Tags: $KERNEL_CVE_TAGS"
    [ -n "$KERNEL_CVE_RANK" ] && KERNEL_CVE_PRINT_LINE="${KERNEL_CVE_PRINT_LINE}${KERNEL_CVE_PRINT_LINE:+ | }Rank: $KERNEL_CVE_RANK"
    [ -n "$KERNEL_CVE_COMMENTS" ] && KERNEL_CVE_PRINT_LINE="${KERNEL_CVE_PRINT_LINE}${KERNEL_CVE_PRINT_LINE:+ | }Details: $KERNEL_CVE_COMMENTS"
    [ -z "$KERNEL_CVE_PRINT_LINE" ] && KERNEL_CVE_PRINT_LINE="Kernel vuln matched with no printable metadata"
    printf "%s\n" "$KERNEL_CVE_PRINT_LINE" | sed -${E} "s,.*,${SED_RED_YELLOW},"
}
kercve_run_registry() {
    KERNEL_CVE_KERNEL_OS=$(uname -s 2>/dev/null)
    KERNEL_CVE_KERNEL_RELEASE=$(uname -r 2>/dev/null)
    KERNEL_CVE_KERNEL_VERSION=$(kercve_norm_ver "$KERNEL_CVE_KERNEL_RELEASE")
    KERNEL_CVE_KERNEL_ARCH=$(uname -m 2>/dev/null)
    KERNEL_CVE_CFG_SOURCE=""
    for KERNEL_CVE_CFG_FILE in "/proc/config.gz" "/boot/config-$KERNEL_CVE_KERNEL_RELEASE" "/lib/modules/$KERNEL_CVE_KERNEL_RELEASE/build/.config" "/usr/lib/modules/$KERNEL_CVE_KERNEL_RELEASE/build/.config" "/usr/src/linux/.config"; do
        if [ -r "$KERNEL_CVE_CFG_FILE" ]; then
            KERNEL_CVE_CFG_SOURCE="$KERNEL_CVE_CFG_FILE"
            break
        fi
    done
    KERNEL_CVE_ALL_DATA=$(printf "%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s\n%s" \
        "$KERNEL_CVE_DATA_1" "$KERNEL_CVE_DATA_2" "$KERNEL_CVE_DATA_3" "$KERNEL_CVE_DATA_4" "$KERNEL_CVE_DATA_5" \
        "$KERNEL_CVE_DATA_6" "$KERNEL_CVE_DATA_7" "$KERNEL_CVE_DATA_8" "$KERNEL_CVE_DATA_9" "$KERNEL_CVE_DATA_10" \
        "$KERNEL_CVE_DATA_11" "$KERNEL_CVE_DATA_12" "$KERNEL_CVE_DATA_13" "$KERNEL_CVE_DATA_14" "$KERNEL_CVE_DATA_15" \
        "$KERNEL_CVE_DATA_16" "$KERNEL_CVE_DATA_17" "$KERNEL_CVE_DATA_18" "$KERNEL_CVE_DATA_19" "$KERNEL_CVE_DATA_20" \
        "$KERNEL_CVE_DATA_21" "$KERNEL_CVE_DATA_22" "$KERNEL_CVE_DATA_23" "$KERNEL_CVE_DATA_24")
    print_list "Operating system ............. $KERNEL_CVE_KERNEL_OS\n"
    print_list "Kernel release ............... $KERNEL_CVE_KERNEL_RELEASE\n"
    print_list "Comparable version ........... $KERNEL_CVE_KERNEL_VERSION\n"
    print_list "Data chunk limit ............. max 25 rows per KERNEL_CVE_DATA_* variable (1..24)\n"
    if [ -n "$KERNEL_CVE_CFG_SOURCE" ]; then
        print_list "Kernel config source ......... $KERNEL_CVE_CFG_SOURCE\n"
    else
        print_list "Kernel config source ......... "
        echo_not_found "not available"
    fi
    if [ "$KERNEL_CVE_KERNEL_OS" != "Linux" ]; then
        print_list "Registry status .............. Linux kernel CVE datasets are not applicable to $KERNEL_CVE_KERNEL_OS\n" | sed -${E} "s,.*,${SED_GREEN},"
        return 0
    fi
    KERNEL_CVE_MATCHES=0
    while IFS="	" read -r KERNEL_CVE_ID KERNEL_CVE_NAME KERNEL_CVE_REQS KERNEL_CVE_TAGS KERNEL_CVE_RANK KERNEL_CVE_COMMENTS; do
        [ -z "$KERNEL_CVE_ID" ] && continue
        KERNEL_CVE_TOKEN_OK=1
        if printf "%s" "$KERNEL_CVE_REQS" | grep -Eq '^pkg=|^ver|CONFIG_|sysctl:|cmd:|,pkg=|,ver|,CONFIG_|,sysctl:|,cmd:'; then
            KERNEL_CVE_REQ_LINES=$(printf "%s" "$KERNEL_CVE_REQS" | tr ',' '\n')
            while IFS= read -r KERNEL_CVE_REQ; do
                KERNEL_CVE_REQ=$(printf "%s" "$KERNEL_CVE_REQ" | sed 's/^ *//;s/ *$//')
                if ! kercve_eval_req_token "$KERNEL_CVE_REQ"; then
                    KERNEL_CVE_TOKEN_OK=0
                    break
                fi
            done <<EOFR
$KERNEL_CVE_REQ_LINES
EOFR
        else
            if ! kercve_match_version_list "$KERNEL_CVE_REQS"; then
                KERNEL_CVE_TOKEN_OK=0
            fi
        fi
        [ "$KERNEL_CVE_TOKEN_OK" -eq 0 ] && continue
        # Some embedded datasets store rows as: <exploit_name> <cve_id> <versions> ...
        # while others store: <cve_id> <exploit_name> <reqs> ...
        # Normalize whichever column contains the CVE identifier, but keep printing
        # all matched vulns even when no CVE exists for that row.
        KERNEL_CVE_ID_RAW="$KERNEL_CVE_ID"
        KERNEL_CVE_ID_NORM=$(kercve_normalize_cve_list "$KERNEL_CVE_ID_RAW")
        if [ -z "$KERNEL_CVE_ID_NORM" ]; then
            KERNEL_CVE_ID_NORM=$(kercve_normalize_cve_list "$KERNEL_CVE_NAME")
            if [ -n "$KERNEL_CVE_ID_NORM" ]; then
                KERNEL_CVE_NAME="$KERNEL_CVE_ID_RAW"
            fi
        fi
        if [ "$KERNEL_CVE_NAME" = "N/A" ] || [ "$KERNEL_CVE_NAME" = "n/a" ] || [ "$KERNEL_CVE_NAME" = "N\\A" ]; then
            KERNEL_CVE_NAME=""
        fi
        if [ "$KERNEL_CVE_ID_RAW" = "N/A" ] || [ "$KERNEL_CVE_ID_RAW" = "n/a" ] || [ "$KERNEL_CVE_ID_RAW" = "N\\A" ]; then
            KERNEL_CVE_ID_RAW=""
        fi
        KERNEL_CVE_PRINT_ID="$KERNEL_CVE_ID_NORM"
        if [ -z "$KERNEL_CVE_PRINT_ID" ] && printf "%s" "$KERNEL_CVE_ID_RAW" | grep -Eq '^CVE-|^[0-9]{4}-[0-9]+$'; then
            KERNEL_CVE_PRINT_ID=$(kercve_normalize_cve_list "$KERNEL_CVE_ID_RAW")
        fi
        KERNEL_CVE_MATCHES=$((KERNEL_CVE_MATCHES + 1))
        kercve_print_match "$KERNEL_CVE_PRINT_ID" "$KERNEL_CVE_NAME" "$KERNEL_CVE_REQS" "$KERNEL_CVE_TAGS" "$KERNEL_CVE_RANK" "$KERNEL_CVE_COMMENTS"
    done <<EOFD
$KERNEL_CVE_ALL_DATA
EOFD
    KERNEL_CVE_PRINT_REASON="Kernel vulns found: $KERNEL_CVE_MATCHES"
    if [ "$KERNEL_CVE_MATCHES" -gt 0 ]; then
        print_list "$KERNEL_CVE_PRINT_REASON\n" | sed -${E} "s,.*,${SED_RED_YELLOW},"
    else
        print_list "No rule matched current kernel/version prerequisites in embedded datasets.\n" | sed -${E} "s,.*,${SED_GREEN},"
    fi
}

su_try_pwd(){
  BFUSER=$1
  PASSWORDTRY=$2
  trysu=$(echo "$PASSWORDTRY" | timeout 1 su $BFUSER -c whoami 2>/dev/null)
    if [ $? -eq 0 ]; then
    echo "  You can login as $BFUSER using password: $PASSWORDTRY" | sed -${E} "s,.*,${SED_RED_YELLOW},"
  fi
}

lp_version_lt() {
  [ -n "$1" ] && [ -n "$2" ] || return 1
  awk -v lp_a="$1" -v lp_b="$2" 'BEGIN {
    lp_na = split(lp_a, lp_av, ".")
    lp_nb = split(lp_b, lp_bv, ".")
    lp_n = lp_na > lp_nb ? lp_na : lp_nb
    for (lp_i = 1; lp_i <= lp_n; lp_i++) {
      lp_ai = lp_av[lp_i] + 0
      lp_bi = lp_bv[lp_i] + 0
      if (lp_ai < lp_bi) exit 0
      if (lp_ai > lp_bi) exit 1
    }
    exit 1
  }'
}

# Contributor: Arjay Saguisa
df43_norm_ver() {
    printf "%s" "$1" | tr '-' '.' | sed 's/[^0-9.].*$//' | sed 's/\.\./\./g' | sed 's/^\.//' | sed 's/\.$//'
}
df43_ver_cmp() {
    DF43_CURVER=$(df43_norm_ver "$1")
    DF43_REQVER=$(df43_norm_ver "$3")
    DF43_OP="$2"
    [ -z "$DF43_CURVER" ] && return 1
    [ -z "$DF43_REQVER" ] && return 1
    DF43_CMP=$(awk -v a="$DF43_CURVER" -v b="$DF43_REQVER" '
    function clean(v){gsub(/[^0-9]/,"",v); if(v=="")v=0; return v+0}
    BEGIN{
      na=split(a,A,"."); nb=split(b,B,"."); n=(na>nb?na:nb);
      for(i=1;i<=n;i++){
        va=(i<=na?clean(A[i]):0); vb=(i<=nb?clean(B[i]):0);
        if(va<vb){print -1; exit}
        if(va>vb){print 1; exit}
      }
      print 0
    }')
    case "$DF43_OP" in
        '>=') [ "$DF43_CMP" -ge 0 ] ;;
        '<')  [ "$DF43_CMP" -lt 0 ] ;;
        *) return 1 ;;
    esac
}
df43_ver_range() {
    df43_ver_cmp "$1" '>=' "$2" && df43_ver_cmp "$1" '<' "$3"
}
checkDirtyFrag() {
    (
        DF43_KERNEL_OS=$(uname -s 2>/dev/null || echo unknown)
        if [ "$DF43_KERNEL_OS" != "Linux" ]; then
            echo "NOT APPLICABLE: Dirty Frag (CVE-2026-43284 / CVE-2026-43500) affects Linux kernels only." | sed -${E} "s,.*,${SED_GREEN},"
            exit 0
        fi
        DF43_KERNEL_RELEASE=$(uname -r 2>/dev/null || echo unknown)
        DF43_KERNEL_VERSION=$(df43_norm_ver "$DF43_KERNEL_RELEASE")
        DF43_KBUILD=$(uname -v 2>/dev/null || echo unknown)
        DF43_VERSION_KNOWN=""
        [ -n "$DF43_KERNEL_VERSION" ] && DF43_VERSION_KNOWN="yes"
        DF43_ESP_AFFECTED="yes"
        DF43_RXRPC_AFFECTED="yes"
        if [ "$DF43_VERSION_KNOWN" = "yes" ]; then
            DF43_ESP_AFFECTED=""
            if df43_ver_range "$DF43_KERNEL_VERSION" 4.11 5.10.255 \
                || df43_ver_range "$DF43_KERNEL_VERSION" 5.12 5.15.205 \
                || df43_ver_range "$DF43_KERNEL_VERSION" 5.16 6.1.171 \
                || df43_ver_range "$DF43_KERNEL_VERSION" 6.2 6.6.138 \
                || df43_ver_range "$DF43_KERNEL_VERSION" 6.7 6.12.87 \
                || df43_ver_range "$DF43_KERNEL_VERSION" 6.13 6.18.28 \
                || df43_ver_range "$DF43_KERNEL_VERSION" 7.0 7.0.5; then
                DF43_ESP_AFFECTED="yes"
            fi
            DF43_RXRPC_AFFECTED=""
            if printf '%s' "$DF43_KERNEL_RELEASE" | grep -Eq '^5\.3(\.0)?-rc'; then
                printf '%s' "$DF43_KERNEL_RELEASE" | grep -Eq '^5\.3(\.0)?-rc[78]([-.]|$)' && DF43_RXRPC_AFFECTED="yes"
            else
                if df43_ver_range "$DF43_KERNEL_VERSION" 5.3 6.18.29 \
                    || df43_ver_range "$DF43_KERNEL_VERSION" 6.19 7.0.6 \
                    || printf '%s' "$DF43_KERNEL_RELEASE" | grep -Eq '^7\.1(\.0)?-rc[12]([-.]|$)'; then
                    DF43_RXRPC_AFFECTED="yes"
                fi
            fi
        fi
        DF43_ESP_MODS="esp4 esp6 xfrm_user ipcomp4 ipcomp6"
        DF43_RXRPC_MODS="rxrpc"
        DF43_LOADED_ESP=""
        DF43_LOADED_RXRPC=""
        for DF43_MOD in $DF43_ESP_MODS; do
            grep -qE "^${DF43_MOD} " /proc/modules 2>/dev/null \
                && DF43_LOADED_ESP="$DF43_LOADED_ESP $DF43_MOD"
        done
        for DF43_MOD in $DF43_RXRPC_MODS; do
            grep -qE "^${DF43_MOD} " /proc/modules 2>/dev/null \
                && DF43_LOADED_RXRPC="$DF43_LOADED_RXRPC $DF43_MOD"
        done
        DF43_AUTO_ESP=""
        DF43_AUTO_RXRPC=""
        DF43_MODDEP="/lib/modules/${DF43_KERNEL_RELEASE}/modules.dep"
        if [ -r "$DF43_MODDEP" ]; then
            for DF43_MOD in $DF43_ESP_MODS; do
                if grep -qE "(^|/)${DF43_MOD}\.ko(\.[a-z]+)?:" "$DF43_MODDEP" 2>/dev/null; then
                    case " $DF43_LOADED_ESP " in
                        *" $DF43_MOD "*) : ;;
                        *) DF43_AUTO_ESP="$DF43_AUTO_ESP $DF43_MOD" ;;
                    esac
                fi
            done
            for DF43_MOD in $DF43_RXRPC_MODS; do
                if grep -qE "(^|/)${DF43_MOD}\.ko(\.[a-z]+)?:" "$DF43_MODDEP" 2>/dev/null; then
                    case " $DF43_LOADED_RXRPC " in
                        *" $DF43_MOD "*) : ;;
                        *) DF43_AUTO_RXRPC="$DF43_AUTO_RXRPC $DF43_MOD" ;;
                    esac
                fi
            done
        fi
        DF43_BUILTIN_ESP=""
        DF43_BUILTIN_RXRPC=""
        DF43_KCFG=""
        for DF43_C in /proc/config.gz "/boot/config-${DF43_KERNEL_RELEASE}" /boot/config; do
            [ -r "$DF43_C" ] && { DF43_KCFG="$DF43_C"; break; }
        done
        if [ -n "$DF43_KCFG" ]; then
            case "$DF43_KCFG" in
                *.gz) DF43_KCAT="zcat" ;;
                *)    DF43_KCAT="cat" ;;
            esac
            $DF43_KCAT "$DF43_KCFG" 2>/dev/null \
                | grep -qE '^(CONFIG_INET_ESP|CONFIG_INET6_ESP|CONFIG_XFRM_USER|CONFIG_INET_IPCOMP|CONFIG_INET6_IPCOMP)=y' \
                && DF43_BUILTIN_ESP="yes"
            $DF43_KCAT "$DF43_KCFG" 2>/dev/null \
                | grep -qE '^CONFIG_AF_RXRPC=y' \
                && DF43_BUILTIN_RXRPC="yes"
        fi
        DF43_MITIG_ESP=""
        DF43_MITIG_RXRPC=""
        for DF43_MOD in $DF43_ESP_MODS; do
            if grep -rEhsq "^[[:space:]]*(blacklist|install)[[:space:]]+${DF43_MOD}\b" \
                 /etc/modprobe.d/ /run/modprobe.d/ /usr/lib/modprobe.d/ /lib/modprobe.d/ 2>/dev/null; then
                DF43_MITIG_ESP="yes"
                break
            fi
        done
        for DF43_MOD in $DF43_RXRPC_MODS; do
            if grep -rEhsq "^[[:space:]]*(blacklist|install)[[:space:]]+${DF43_MOD}\b" \
                 /etc/modprobe.d/ /run/modprobe.d/ /usr/lib/modprobe.d/ /lib/modprobe.d/ 2>/dev/null; then
                DF43_MITIG_RXRPC="yes"
                break
            fi
        done
        DF43_USERNS_OFF=""
        if [ -r /proc/sys/kernel/unprivileged_userns_clone ]; then
            [ "$(cat /proc/sys/kernel/unprivileged_userns_clone 2>/dev/null)" = "0" ] \
                && DF43_USERNS_OFF="yes"
        fi
        if [ -r /proc/sys/user/max_user_namespaces ]; then
            [ "$(cat /proc/sys/user/max_user_namespaces 2>/dev/null)" = "0" ] \
                && DF43_USERNS_OFF="yes"
        fi
        DF43_CAP_NET_ADMIN=""
        if [ -r /proc/self/status ]; then
            DF43_CAPEFF=$(awk '/^CapEff:/ {print $2}' /proc/self/status 2>/dev/null)
            case "$DF43_CAPEFF" in
                "" | *[!0-9a-fA-F]*) : ;;
                *)
                    DF43_CAPLO=$(printf '%s' "$DF43_CAPEFF" | tail -c 4)
                    [ "$(( 0x${DF43_CAPLO} & 0x1000 ))" -ne 0 ] && DF43_CAP_NET_ADMIN="yes"
                    ;;
            esac
        fi
        DF43_OLDBUILD=""
        DF43_BDATE=$(printf '%s' "$DF43_KBUILD" | sed -nE 's/.*([A-Z][a-z]{2} [A-Z][a-z]{2} +[0-9]{1,2} [0-9:]+ (UTC )?[0-9]{4}).*/\1/p')
        if [ -z "$DF43_BDATE" ]; then
            DF43_BDATE=$(printf '%s' "$DF43_KBUILD" | sed -nE 's/.*\(([0-9]{4}-[0-9]{2}-[0-9]{2})\).*/\1/p')
        fi
        if [ -n "$DF43_BDATE" ]; then
            DF43_BE=$(date -d "$DF43_BDATE" +%s 2>/dev/null)
            DF43_FE=$(date -d '2026-05-08' +%s 2>/dev/null)
            if [ -n "$DF43_BE" ] && [ -n "$DF43_FE" ] && [ "$DF43_BE" -lt "$DF43_FE" ]; then
                DF43_OLDBUILD="yes"
            fi
        fi
        if [ -n "$DF43_LOADED_ESP" ]; then
            if [ "$DF43_ESP_AFFECTED" = "yes" ]; then
                echo "CVE-2026-43284 (xfrm-ESP): loaded:$DF43_LOADED_ESP" | sed -${E} "s,.*,${SED_RED_YELLOW},"
            else
                echo "CVE-2026-43284 (xfrm-ESP): loaded:$DF43_LOADED_ESP but kernel $DF43_KERNEL_RELEASE is outside known affected ranges" | sed -${E} "s,.*,${SED_GREEN},"
            fi
        elif [ "$DF43_BUILTIN_ESP" = "yes" ]; then
            if [ "$DF43_ESP_AFFECTED" = "yes" ]; then
                echo "CVE-2026-43284 (xfrm-ESP): built into kernel (modprobe blacklist ineffective)" | sed -${E} "s,.*,${SED_RED_YELLOW},"
            else
                echo "CVE-2026-43284 (xfrm-ESP): built into kernel, but kernel $DF43_KERNEL_RELEASE is outside known affected ranges" | sed -${E} "s,.*,${SED_GREEN},"
            fi
        elif [ -n "$DF43_AUTO_ESP" ]; then
            if [ "$DF43_ESP_AFFECTED" = "yes" ]; then
                echo "CVE-2026-43284 (xfrm-ESP): autoloadable:$DF43_AUTO_ESP" | sed -${E} "s,.*,${SED_RED_YELLOW},"
            else
                echo "CVE-2026-43284 (xfrm-ESP): autoloadable:$DF43_AUTO_ESP but kernel $DF43_KERNEL_RELEASE is outside known affected ranges" | sed -${E} "s,.*,${SED_GREEN},"
            fi
        else
            echo "CVE-2026-43284 (xfrm-ESP): not reachable on this kernel" | sed -${E} "s,.*,${SED_GREEN},"
        fi
        if [ -n "$DF43_LOADED_RXRPC" ]; then
            if [ "$DF43_RXRPC_AFFECTED" = "yes" ]; then
                echo "CVE-2026-43500 (rxrpc): loaded:$DF43_LOADED_RXRPC" | sed -${E} "s,.*,${SED_RED_YELLOW},"
            else
                echo "CVE-2026-43500 (rxrpc): loaded:$DF43_LOADED_RXRPC but kernel $DF43_KERNEL_RELEASE is outside known affected ranges" | sed -${E} "s,.*,${SED_GREEN},"
            fi
        elif [ "$DF43_BUILTIN_RXRPC" = "yes" ]; then
            if [ "$DF43_RXRPC_AFFECTED" = "yes" ]; then
                echo "CVE-2026-43500 (rxrpc): built into kernel (modprobe blacklist ineffective)" | sed -${E} "s,.*,${SED_RED_YELLOW},"
            else
                echo "CVE-2026-43500 (rxrpc): built into kernel, but kernel $DF43_KERNEL_RELEASE is outside known affected ranges" | sed -${E} "s,.*,${SED_GREEN},"
            fi
        elif [ -n "$DF43_AUTO_RXRPC" ]; then
            if [ "$DF43_RXRPC_AFFECTED" = "yes" ]; then
                echo "CVE-2026-43500 (rxrpc): autoloadable:$DF43_AUTO_RXRPC" | sed -${E} "s,.*,${SED_RED_YELLOW},"
            else
                echo "CVE-2026-43500 (rxrpc): autoloadable:$DF43_AUTO_RXRPC but kernel $DF43_KERNEL_RELEASE is outside known affected ranges" | sed -${E} "s,.*,${SED_GREEN},"
            fi
        else
            echo "CVE-2026-43500 (rxrpc): not reachable on this kernel" | sed -${E} "s,.*,${SED_GREEN},"
        fi
        if [ "$DF43_MITIG_ESP" = "yes" ]; then
            echo "modprobe mitigation (xfrm-ESP): present" | sed -${E} "s,.*,${SED_GREEN},"
        else
            echo "modprobe mitigation (xfrm-ESP): not found" | sed -${E} "s,.*,${SED_YELLOW},"
        fi
        if [ "$DF43_MITIG_RXRPC" = "yes" ]; then
            echo "modprobe mitigation (rxrpc): present" | sed -${E} "s,.*,${SED_GREEN},"
        else
            echo "modprobe mitigation (rxrpc): not found" | sed -${E} "s,.*,${SED_YELLOW},"
        fi
        if [ "$DF43_USERNS_OFF" = "yes" ]; then
            echo "Unprivileged user namespaces: disabled (breaks the public PoC)" | sed -${E} "s,.*,${SED_GREEN},"
        else
            echo "Unprivileged user namespaces: enabled" | sed -${E} "s,.*,${SED_YELLOW},"
        fi
        if [ "$DF43_CAP_NET_ADMIN" = "yes" ]; then
            echo "Current process: CAP_NET_ADMIN present (matches public PoC requirement)" | sed -${E} "s,.*,${SED_RED_YELLOW},"
        fi
        if [ "$DF43_OLDBUILD" = "yes" ]; then
            echo "Kernel build predates upstream fix (2026-05-08): likely unpatched unless distro backport." | sed -${E} "s,.*,${SED_YELLOW},"
        fi
        DF43_ESP_REACH=""
        [ -n "$DF43_LOADED_ESP$DF43_AUTO_ESP" ] && DF43_ESP_REACH="yes"
        [ "$DF43_BUILTIN_ESP" = "yes" ] && DF43_ESP_REACH="yes"
        DF43_RXRPC_REACH=""
        [ -n "$DF43_LOADED_RXRPC$DF43_AUTO_RXRPC" ] && DF43_RXRPC_REACH="yes"
        [ "$DF43_BUILTIN_RXRPC" = "yes" ] && DF43_RXRPC_REACH="yes"
        DF43_RC=0
        if [ "$DF43_ESP_REACH" = "yes" ] && [ "$DF43_MITIG_ESP" != "yes" ]; then
            if [ "$DF43_ESP_AFFECTED" != "yes" ]; then
                :
            elif [ "$DF43_USERNS_OFF" = "yes" ]; then
                echo "CVE-2026-43284 reachable but public PoC blocked by disabled user namespaces." | sed -${E} "s,.*,${SED_YELLOW},"
                [ $DF43_RC -lt 1 ] && DF43_RC=1
            else
                echo "LIKELY VULNERABLE to CVE-2026-43284 (xfrm-ESP)." | sed -${E} "s,.*,${SED_RED_YELLOW},"
                DF43_RC=2
            fi
        fi
        if [ "$DF43_RXRPC_REACH" = "yes" ] && [ "$DF43_MITIG_RXRPC" != "yes" ]; then
            if [ "$DF43_RXRPC_AFFECTED" != "yes" ]; then
                :
            elif [ "$DF43_USERNS_OFF" = "yes" ]; then
                echo "CVE-2026-43500 reachable but public PoC blocked by disabled user namespaces." | sed -${E} "s,.*,${SED_YELLOW},"
                [ $DF43_RC -lt 1 ] && DF43_RC=1
            else
                echo "LIKELY VULNERABLE to CVE-2026-43500 (rxrpc)." | sed -${E} "s,.*,${SED_RED_YELLOW},"
                DF43_RC=2
            fi
        fi
        if [ $DF43_RC -gt 0 ]; then
            echo "Mitigation: 'install esp4/esp6/rxrpc /bin/false' in /etc/modprobe.d/, then rmmod;"
            echo "or sysctl kernel.unprivileged_userns_clone=0; or apply distro patches."
        fi
        exit $DF43_RC
    )
}

lp_extract_upstream_version() {
  printf '%s' "$1" | sed -E 's/^[0-9]+://; s/^[^0-9]*//; s/[^0-9.].*$//'
}

linpeas_json_escape(){
  printf "%s" "$1" | sed 's/\\/\\\\/g; s/"/\\"/g; s/	/ /g'
}
linpeas_os_release_field(){
  [ -r /etc/os-release ] || return
  awk -F= -v key="$1" '
    $1 == key {
      value=$0
      sub(/^[^=]*=/, "", value)
      gsub(/^"/, "", value)
      gsub(/"$/, "", value)
      print value
      exit
    }
  ' /etc/os-release 2>/dev/null
}
linpeas_os_package_ecosystem(){
  _os_id="$(linpeas_os_release_field ID)"
  _os_version_id="$(linpeas_os_release_field VERSION_ID)"
  _os_version_major="$(printf "%s" "$_os_version_id" | cut -d. -f1)"
  case "$_os_id" in
    debian)  [ "$_os_version_major" ] && printf "Debian:%s" "$_os_version_major" ;;
    ubuntu)  [ "$_os_version_id" ] && printf "Ubuntu:%s" "$_os_version_id" ;;
    alpine)  [ "$_os_version_id" ] && printf "Alpine:v%s" "$_os_version_id" ;;
    fedora)  [ "$_os_version_id" ] && printf "Fedora:%s" "$_os_version_id" ;;
    amzn)    [ "$_os_version_id" ] && printf "Amazon Linux:%s" "$_os_version_id" ;;
    rhel)    [ "$_os_version_major" ] && printf "Red Hat:%s" "$_os_version_major" ;;
    centos)  [ "$_os_version_major" ] && printf "CentOS:%s" "$_os_version_major" ;;
    rocky)   [ "$_os_version_major" ] && printf "Rocky Linux:%s" "$_os_version_major" ;;
    almalinux) [ "$_os_version_major" ] && printf "AlmaLinux:%s" "$_os_version_major" ;;
  esac
}
linpeas_tabbed_packages_to_json_lines(){
  awk -F '\t' -v manager="$1" -v ecosystem="$2" '
    function esc(s) { gsub(/\\/,"\\\\",s); gsub(/"/,"\\\"",s); gsub(/\r/," ",s); return s }
    $1 != "" && $2 != "" {
      key=$1 "|" $2
      if (seen[key]++) next
      printf "{\"name\":\"%s\",\"version\":\"%s\",\"ecosystem\":\"%s\",\"manager\":\"%s\"}\n", esc($1), esc($2), esc(ecosystem), manager
    }'
}
linpeas_print_package_json_lines(){
  _ecosystem="$(linpeas_os_package_ecosystem)"
  if command -v dpkg-query >/dev/null 2>&1; then
    dpkg-query -W -f='${source:Package}\t${source:Version}\t${binary:Package}\t${Version}\n' 2>/dev/null | awk -F '\t' '
      {
        name=$1; version=$2
        if (name == "" || name == "-") { name=$3; version=$4 }
        if (version == "" || version == "-") { version=$4 }
        sub(/^src:/, "", name)
        if (name == "" || version == "") next
        printf "%s\t%s\n", name, version
      }' | linpeas_tabbed_packages_to_json_lines "dpkg" "$_ecosystem"
  elif command -v rpm >/dev/null 2>&1; then
    rpm -qa --qf '%{NAME}\t%{VERSION}-%{RELEASE}\n' 2>/dev/null | linpeas_tabbed_packages_to_json_lines "rpm" "$_ecosystem"
  elif command -v apk >/dev/null 2>&1; then
    apk info 2>/dev/null | while IFS= read -r _pkg_name; do
      [ "$_pkg_name" ] || continue
      _pkg_line="$(apk info -e -v "$_pkg_name" 2>/dev/null | head -n 1)"
      _pkg_version="$(printf "%s" "$_pkg_line" | awk -v n="$_pkg_name" 'index($0, n "-") == 1 { print substr($0, length(n) + 2); exit }')"
      [ "$_pkg_version" ] || continue
      printf '{"name":"%s","version":"%s","ecosystem":"%s","manager":"apk"}\n' \
        "$(linpeas_json_escape "$_pkg_name")" "$(linpeas_json_escape "$_pkg_version")" "$(linpeas_json_escape "$_ecosystem")"
    done
  elif command -v pacman >/dev/null 2>&1; then
    pacman -Q 2>/dev/null | linpeas_tabbed_packages_to_json_lines "pacman" "$_ecosystem"
  fi
}
linpeas_packages_json(){
  _limit="${HACKTRICKS_PACKAGE_LIMIT:-300}"
  linpeas_print_package_json_lines | awk -v max="$_limit" '
    BEGIN { first=1; printf "[" }
    NF {
      if (count >= max) next
      if (!first) printf ","
      printf "%s", $0
      first=0
      count++
    }
    END { printf "]" }'
}
linpeas_os_json(){
  _os_id="$(linpeas_os_release_field ID)"
  _os_name="$(linpeas_os_release_field PRETTY_NAME)"
  _os_version_id="$(linpeas_os_release_field VERSION_ID)"
  _os_codename="$(linpeas_os_release_field VERSION_CODENAME)"
  printf '{"id":"%s","name":"%s","version_id":"%s","codename":"%s","kernel":{"release":"%s","version":"%s","arch":"%s"}}' \
    "$(linpeas_json_escape "$_os_id")" \
    "$(linpeas_json_escape "$_os_name")" \
    "$(linpeas_json_escape "$_os_version_id")" \
    "$(linpeas_json_escape "$_os_codename")" \
    "$(linpeas_json_escape "$(uname -r 2>/dev/null)")" \
    "$(linpeas_json_escape "$(uname -v 2>/dev/null)")" \
    "$(linpeas_json_escape "$(uname -m 2>/dev/null)")"
}
linpeas_host_checker_payload(){
  _hostname="$(hostname 2>/dev/null)"
  if [ "$ONLINE_VULN_CHECKS" ]; then
    printf '{"hostname":"%s","source":"linpeas","version":"%s","online_package_check":true,"os":%s,"packages":%s}' \
      "$(linpeas_json_escape "$_hostname")" \
      "$(linpeas_json_escape "$VERSION")" \
      "$(linpeas_os_json)" \
      "$(linpeas_packages_json)"
  else
    printf '{"hostname":"%s","source":"linpeas","version":"%s"}' \
      "$(linpeas_json_escape "$_hostname")" \
      "$(linpeas_json_escape "$VERSION")"
  fi
}
linpeas_start_host_checker_lookup(){
  [ "$NOT_CHECK_EXTERNAL_HOSTNAME" ] && return
  [ "$LINPEAS_HOST_CHECKER_STARTED" ] && return
  INTERNET_SEARCH_TIMEOUT=15
  LINPEAS_HOST_CHECKER_STARTED="1"
  LINPEAS_HOST_CHECKER_OUT="${TMPDIR:-/tmp}/linpeas_host_checker_$$.json"
  LINPEAS_HOST_CHECKER_ERR="${TMPDIR:-/tmp}/linpeas_host_checker_$$.err"
  _hacktricks_host_checker_url="${HACKTRICKS_HOST_CHECKER_URL:-https://tools.hacktricks.wiki/api/host-checker}"
  _hacktricks_payload="$(linpeas_host_checker_payload)"
  if command -v curl >/dev/null 2>&1; then
    (curl -s "$_hacktricks_host_checker_url" -H "User-Agent: linpeas" --data-binary "$_hacktricks_payload" -H "Content-Type: application/json" --max-time "$INTERNET_SEARCH_TIMEOUT" > "$LINPEAS_HOST_CHECKER_OUT" 2>"$LINPEAS_HOST_CHECKER_ERR") &
    LINPEAS_HOST_CHECKER_PID=$!
  elif command -v wget >/dev/null 2>&1; then
    (wget -q -O - "$_hacktricks_host_checker_url" --header "User-Agent: linpeas" --header "Content-Type: application/json" --post-data "$_hacktricks_payload" --timeout "$INTERNET_SEARCH_TIMEOUT" > "$LINPEAS_HOST_CHECKER_OUT" 2>"$LINPEAS_HOST_CHECKER_ERR") &
    LINPEAS_HOST_CHECKER_PID=$!
  else
    printf '{"error":"wget or curl not found"}\n' > "$LINPEAS_HOST_CHECKER_OUT"
  fi
}
linpeas_wait_host_checker_lookup(){
  [ "$NOT_CHECK_EXTERNAL_HOSTNAME" ] && return 1
  linpeas_start_host_checker_lookup
  if [ "$LINPEAS_HOST_CHECKER_PID" ]; then
    wait "$LINPEAS_HOST_CHECKER_PID" 2>/dev/null
    LINPEAS_HOST_CHECKER_PID=""
  fi
  [ -s "$LINPEAS_HOST_CHECKER_OUT" ]
}
linpeas_strip_package_vulns_from_host_response(){
  if command -v jq >/dev/null 2>&1; then
    jq 'del(.package_vulnerabilities)' "$LINPEAS_HOST_CHECKER_OUT" 2>/dev/null && return
  fi
  awk '
    function brace_delta(s, t, opens, closes) {
      t=s; opens=gsub(/{/,"{",t)
      t=s; closes=gsub(/}/,"}",t)
      return opens - closes
    }
    skip {
      depth += brace_delta($0)
      if (depth <= 0) skip=0
      next
    }
    /"package_vulnerabilities"[[:space:]]*:/ {
      sub(/,[[:space:]]*$/, "", prev)
      skip=1
      depth=brace_delta($0)
      if (depth <= 0) skip=0
      next
    }
    {
      if (have) print prev
      prev=$0
      have=1
    }
    END {
      if (have) print prev
    }
  ' "$LINPEAS_HOST_CHECKER_OUT"
}
check_external_hostname(){
  if linpeas_wait_host_checker_lookup; then
    linpeas_strip_package_vulns_from_host_response
  else
    echo "HackTricks host checker did not return data"
  fi
}
linpeas_print_package_vulnerabilities_with_jq(){
  jq -r '
    .package_vulnerabilities as $pv
    | if ($pv == null) then
        empty
      elif (($pv.affected // 0) | tonumber) == 0 then
        "No vulnerable packages found by online lookup (checked \($pv.checked // 0) packages)."
      else
        "Online package vulnerabilities found: \($pv.affected) vulnerable package(s), checked \($pv.checked // 0).",
        (
          $pv.vulnerable_packages[:50][]?
          | "- \(.name // "?") \(.version // "?") [\(.ecosystem // "unknown")]: \((.vulns // []) | join(", "))"
        ),
        (
          if (($pv.vulnerable_packages | length) > 50) then
            "... \((($pv.vulnerable_packages | length) - 50)) more vulnerable package(s) not shown."
          else empty end
        )
      end
  ' "$LINPEAS_HOST_CHECKER_OUT" 2>/dev/null
}
linpeas_print_package_vulnerabilities_with_awk(){
  awk '
    function json_value(line) {
      sub(/^[^:]*:[[:space:]]*"/, "", line)
      sub(/",?[[:space:]]*$/, "", line)
      return line
    }
    function json_number(line) {
      sub(/^[^:]*:[[:space:]]*/, "", line)
      sub(/,?[[:space:]]*$/, "", line)
      return line
    }
    function json_string(line) {
      sub(/^[[:space:]]*"/, "", line)
      sub(/",?[[:space:]]*$/, "", line)
      return line
    }
    function flush_pkg() {
      if (name != "" && version != "") {
        total++
        if (shown < 50) {
          print "- " name " " version " [" (ecosystem != "" ? ecosystem : "unknown") "]: " vulns
          shown++
        }
      }
      name=""; version=""; ecosystem=""; vulns=""; in_vulns=0
    }
    /"package_vulnerabilities"[[:space:]]*:/ { in_pv=1; next }
    in_pv && /"checked"[[:space:]]*:/ { checked=json_number($0); next }
    in_pv && /"affected"[[:space:]]*:/ { affected=json_number($0); next }
    in_pv && /"vulnerable_packages"[[:space:]]*:[[:space:]]*\[/ { in_pkgs=1; next }
    in_pkgs && /"name"[[:space:]]*:/ { name=json_value($0); next }
    in_pkgs && /"version"[[:space:]]*:/ { version=json_value($0); next }
    in_pkgs && /"ecosystem"[[:space:]]*:/ { ecosystem=json_value($0); next }
    in_pkgs && /"vulns"[[:space:]]*:[[:space:]]*\[/ { in_vulns=1; next }
    in_vulns && /"/ {
      v=json_string($0)
      if (v != "") vulns = vulns (vulns != "" ? ", " : "") v
      next
    }
    in_vulns && /\]/ { in_vulns=0; next }
    in_pkgs && /^[[:space:]]*}[,]?[[:space:]]*$/ { flush_pkg(); next }
    END {
      if (affected == "") exit
      if ((affected + 0) == 0) {
        print "No vulnerable packages found by online lookup (checked " (checked != "" ? checked : 0) " packages)."
      } else {
        print "Online package vulnerabilities found: " affected " vulnerable package(s), checked " (checked != "" ? checked : 0) "."
        if (total > 50) print "... " (total - 50) " more vulnerable package(s) not shown."
      }
    }
  ' "$LINPEAS_HOST_CHECKER_OUT" | awk '
    /^Online package vulnerabilities found:/ { header=$0; next }
    /^No vulnerable packages found/ { print; next }
    /^\.\.\. / { more=$0; next }
    /^- / { lines[++count]=$0; next }
    END {
      if (header) print header
      for (i=1; i<=count && i<=50; i++) print lines[i]
      if (more) print more
    }
  '
}
linpeas_print_package_vulnerabilities(){
  [ "$ONLINE_VULN_CHECKS" ] || return
  if ! linpeas_wait_host_checker_lookup; then
    echo "Online package vulnerability lookup did not return data"
    return
  fi
  if command -v jq >/dev/null 2>&1; then
    linpeas_print_package_vulnerabilities_with_jq | sed -${E} "s,CVE-[0-9]{4}-[0-9]+,${SED_RED_YELLOW},g"
  else
    linpeas_print_package_vulnerabilities_with_awk | sed -${E} "s,CVE-[0-9]{4}-[0-9]+,${SED_RED_YELLOW},g"
  fi
}

ud7867_fixed_dpkg_version() {
  # Known vendor backports from Debian DSA-6414-1 and Ubuntu USN-8701-1.
  case "$1:$2" in
    debian:trixie) echo "2.10.1-12.1+deb13u2" ;;
    debian:forky|debian:sid) echo "2.11.2-1" ;;
    ubuntu:noble) echo "2.10.1-6ubuntu1.5" ;;
    ubuntu:resolute) echo "2.10.91-1ubuntu2.1" ;;
  esac
}
checkUDisksCVE20267867() {
  [ "$(uname -s 2>/dev/null)" = "Linux" ] || return 0
  ud7867_root="${ROOT_FOLDER:-/}"
  case "$ud7867_root" in
    */) ;;
    *) ud7867_root="${ud7867_root}/" ;;
  esac
  ud7867_fstab="${ud7867_root}etc/fstab"
  [ -r "$ud7867_fstab" ] || return 0
  ud7867_fstab_matches="$(awk '
    /^[[:space:]]*#/ || NF < 4 { next }
    {
      ud7867_count = split($4, ud7867_options, ",")
      for (ud7867_i = 1; ud7867_i <= ud7867_count; ud7867_i++) {
        if (ud7867_options[ud7867_i] == "user" ||
            ud7867_options[ud7867_i] == "users" ||
            ud7867_options[ud7867_i] == "x-udisks-auth") {
          print
          next
        }
      }
    }
  ' "$ud7867_fstab" 2>/dev/null | head -n 10)"
  [ -n "$ud7867_fstab_matches" ] || return 0
  ud7867_binary=""
  for ud7867_binary_candidate in usr/libexec/udisks2/udisksd usr/lib/udisks2/udisksd lib/udisks2/udisksd; do
    if [ -x "${ud7867_root}${ud7867_binary_candidate}" ]; then
      ud7867_binary="${ud7867_root}${ud7867_binary_candidate}"
      break
    fi
  done
  [ -n "$ud7867_binary" ] || return 0
  ud7867_service_file="${ud7867_root}usr/share/dbus-1/system-services/org.freedesktop.UDisks2.service"
  [ -r "$ud7867_service_file" ] || return 0
  ud7867_full_version=""
  ud7867_manager=""
  if command -v dpkg-query >/dev/null 2>&1; then
    ud7867_dpkg_record="$(dpkg-query --admindir="${ud7867_root}var/lib/dpkg" -W -f='$''{Status}|$''{Version}\n' udisks2 2>/dev/null | head -n1)"
    case "$ud7867_dpkg_record" in
      "install ok installed|"*)
        ud7867_full_version="${ud7867_dpkg_record#*|}"
        [ -n "$ud7867_full_version" ] && ud7867_manager="dpkg"
        ;;
    esac
  fi
  if [ -z "$ud7867_full_version" ] && command -v rpm >/dev/null 2>&1; then
    if ud7867_rpm_record="$(rpm --root "$ud7867_root" -q --qf '%{VERSION}-%{RELEASE}\n' udisks2 2>/dev/null)"; then
      ud7867_full_version="$(printf '%s\n' "$ud7867_rpm_record" | head -n1)"
      [ -n "$ud7867_full_version" ] && ud7867_manager="rpm"
    fi
  fi
  [ -n "$ud7867_full_version" ] || return 0
  ud7867_os_release="${ud7867_root}etc/os-release"
  ud7867_distro_id="$(sed -nE 's/^ID="?([^" ]+)"?$/\1/p' "$ud7867_os_release" 2>/dev/null | head -n1)"
  ud7867_codename="$(sed -nE 's/^VERSION_CODENAME="?([^" ]+)"?$/\1/p' "$ud7867_os_release" 2>/dev/null | head -n1)"
  ud7867_ubuntu_codename="$(sed -nE 's/^UBUNTU_CODENAME="?([^" ]+)"?$/\1/p' "$ud7867_os_release" 2>/dev/null | head -n1)"
  if [ -n "$ud7867_ubuntu_codename" ]; then
    ud7867_distro_id="ubuntu"
    ud7867_codename="$ud7867_ubuntu_codename"
  fi
  ud7867_upstream_version="$(lp_extract_upstream_version "$ud7867_full_version")"
  ud7867_dpkg_fixed=""
  ud7867_status="unknown"
  if [ "$ud7867_manager" = "dpkg" ] && command -v dpkg >/dev/null 2>&1; then
    ud7867_dpkg_fixed="$(ud7867_fixed_dpkg_version "$ud7867_distro_id" "$ud7867_codename")"
    if [ -n "$ud7867_dpkg_fixed" ]; then
      if dpkg --compare-versions "$ud7867_full_version" lt "$ud7867_dpkg_fixed"; then
        ud7867_status="affected"
      else
        ud7867_status="fixed"
      fi
    fi
  fi
  # RPM vendors commonly retain their old upstream version after backporting.
  if [ "$ud7867_status" = "unknown" ] && [ "$ud7867_manager" = "rpm" ]; then
    if rpm --root "$ud7867_root" -q --changelog udisks2 2>/dev/null | grep -q 'CVE-2026-7867'; then
      ud7867_status="fixed"
    fi
  fi
  if [ "$ud7867_status" = "unknown" ] && [ -n "$ud7867_upstream_version" ]; then
    if lp_version_lt "$ud7867_upstream_version" "2.10.0"; then
      ud7867_status="fixed"
    elif lp_version_lt "$ud7867_upstream_version" "2.11.2"; then
      ud7867_status="potential"
    else
      ud7867_status="fixed"
    fi
  fi
  [ "$ud7867_status" = "affected" ] || [ "$ud7867_status" = "potential" ] || return 0
  print_3title "UDisks as-user mount authorization bypass (CVE-2026-7867)" "T1068"
  print_info "https://github.com/storaged-project/udisks/security/advisories/GHSA-j42g-v9jw-6ph3"
  echo "udisks2 package: $ud7867_full_version ($ud7867_manager)" | sed -${E} "s,.*,${SED_LIGHT_CYAN},"
  if [ "$ud7867_status" = "affected" ]; then
    echo "VULNERABLE to CVE-2026-7867: package is below the known vendor fixed version and a qualifying fstab entry is present" | sed -${E} "s,.*,${SED_RED_YELLOW},"
  else
    echo "Potentially vulnerable to CVE-2026-7867: upstream version is in the affected range 2.10.0 through 2.11.1; verify vendor backports" | sed -${E} "s,.*,${SED_RED_YELLOW},"
  fi
  echo "Qualifying /etc/fstab entries (maximum 10):"
  printf '%s\n' "$ud7867_fstab_matches"
  echo ""
}

xft80530_version_lt() {
  [ -n "$1" ] && [ -n "$2" ] || return 1
  awk -v xft80530_a="$1" -v xft80530_b="$2" 'BEGIN {
    xft80530_na = split(xft80530_a, xft80530_av, ".")
    xft80530_nb = split(xft80530_b, xft80530_bv, ".")
    xft80530_n = xft80530_na > xft80530_nb ? xft80530_na : xft80530_nb
    for (xft80530_i = 1; xft80530_i <= xft80530_n; xft80530_i++) {
      xft80530_ai = xft80530_av[xft80530_i] + 0
      xft80530_bi = xft80530_bv[xft80530_i] + 0
      if (xft80530_ai < xft80530_bi) exit 0
      if (xft80530_ai > xft80530_bi) exit 1
    }
    exit 1
  }'
}
xft80530_kernel_status() {
  case "$1" in
    7.2.0-rc*)
      xft80530_rc="$(printf '%s' "$1" | sed -nE 's/^7\.2\.0-rc([0-9]+).*/\1/p')"
      if [ -n "$xft80530_rc" ] && [ "$xft80530_rc" -ge 7 ]; then
        echo "fixed"
      else
        echo "affected"
      fi
      return
      ;;
  esac
  xft80530_version="$(printf '%s' "$1" | sed -nE 's/^([0-9]+\.[0-9]+\.[0-9]+).*/\1/p')"
  if [ -z "$xft80530_version" ]; then
    echo "unknown"
  elif xft80530_version_lt "$xft80530_version" "6.10.0"; then
    echo "predates"
  elif ! xft80530_version_lt "$xft80530_version" "7.2.0"; then
    echo "fixed"
  else
    case "$xft80530_version" in
      6.12.*)
        if ! xft80530_version_lt "$xft80530_version" "6.12.105"; then
          echo "fixed"
        else
          echo "affected"
        fi
        ;;
      6.18.*)
        if ! xft80530_version_lt "$xft80530_version" "6.18.46"; then
          echo "fixed"
        else
          echo "affected"
        fi
        ;;
      7.1.*)
        if ! xft80530_version_lt "$xft80530_version" "7.1.10"; then
          echo "fixed"
        else
          echo "affected"
        fi
        ;;
      *) echo "affected" ;;
    esac
  fi
}
checkXFSTangoCVE202680530() {
  [ "$(uname -s 2>/dev/null)" = "Linux" ] || return 0
  xft80530_kernel="${1:-$(uname -r 2>/dev/null)}"
  xft80530_mount_file="${2:-/proc/self/mounts}"
  xft80530_os_release="${3:-/etc/os-release}"
  [ -r "$xft80530_mount_file" ] || return 0
  # Limit filesystem queries on hosts with very large mount namespaces.
  xft80530_mounts="$(awk '$3 == "xfs" { print $2 }' "$xft80530_mount_file" 2>/dev/null | head -n 20)"
  [ -n "$xft80530_mounts" ] || return 0
  xft80530_status="$(xft80530_kernel_status "$xft80530_kernel")"
  xft80530_distro_id="$(sed -nE 's/^ID="?([^" ]+)"?$/\1/p' "$xft80530_os_release" 2>/dev/null | head -n1)"
  xft80530_distro_version="$(sed -nE 's/^VERSION_ID="?([^" ]+)"?$/\1/p' "$xft80530_os_release" 2>/dev/null | head -n1)"
  # Red Hat confirms that its 5.14-based RHEL 9 kernel backported the
  # vulnerable code, while RHEL 10 did not.  Do not trust upstream version
  # boundaries alone for these vendor kernels.
  case "$xft80530_distro_id:$xft80530_distro_version" in
    rhel:9*|centos:9*|rocky:9*|almalinux:9*) xft80530_status="vendor_affected" ;;
    rhel:10*) xft80530_status="vendor_unaffected" ;;
  esac
  xft80530_reflink_enabled=0
  xft80530_reflink_unknown=0
  print_3title "XFSTango XFS reflink LPE (CVE-2026-80530)" "T1068"
  print_info "https://seclists.org/oss-sec/2026/q3/641"
  echo "Kernel: $xft80530_kernel" | sed -${E} "s,.*,${SED_LIGHT_CYAN},"
  echo "Mounted XFS filesystems (maximum 20):"
  while IFS= read -r xft80530_mountpoint_escaped; do
    [ -n "$xft80530_mountpoint_escaped" ] || continue
    # /proc/self/mounts represents whitespace as octal escapes.
    xft80530_mountpoint="$(printf '%b' "$xft80530_mountpoint_escaped")"
    xft80530_info=""
    if [ -n "$TIMEOUT" ] && command -v xfs_info >/dev/null 2>&1; then
      xft80530_info="$("$TIMEOUT" 2 xfs_info "$xft80530_mountpoint" 2>/dev/null)"
    fi
    if printf '%s\n' "$xft80530_info" | grep -Eq '(^|[[:space:]])reflink=1([[:space:]]|$)'; then
      xft80530_reflink_status="enabled"
      xft80530_reflink_enabled=$((xft80530_reflink_enabled + 1))
    elif printf '%s\n' "$xft80530_info" | grep -Eq '(^|[[:space:]])reflink=0([[:space:]]|$)'; then
      xft80530_reflink_status="disabled"
    else
      xft80530_reflink_status="unknown (xfs_info unavailable or inconclusive)"
      xft80530_reflink_unknown=$((xft80530_reflink_unknown + 1))
    fi
    printf '  %s - reflink %s\n' "$xft80530_mountpoint" "$xft80530_reflink_status"
  done <<EOF
$xft80530_mounts
EOF
  case "$xft80530_status" in
    predates)
      echo "NOT VULNERABLE: upstream kernel $xft80530_kernel predates the vulnerable code introduced in 6.10" | sed -${E} "s,.*,${SED_GREEN},"
      ;;
    fixed)
      echo "NOT VULNERABLE by upstream version: kernel $xft80530_kernel is at or after a known fixed release" | sed -${E} "s,.*,${SED_GREEN},"
      ;;
    vendor_unaffected)
      echo "NOT VULNERABLE according to the Red Hat advisory: this RHEL 10-family kernel did not include the vulnerable code" | sed -${E} "s,.*,${SED_GREEN},"
      ;;
    affected|vendor_affected)
      if [ "$xft80530_reflink_enabled" -gt 0 ]; then
        if [ "$xft80530_status" = "vendor_affected" ]; then
          echo "POTENTIALLY VULNERABLE to CVE-2026-80530: this is a RHEL 9-family kernel (Red Hat lists RHEL 9 affected despite its 5.14 base), and XFS reflink is enabled" | sed -${E} "s,.*,${SED_RED_YELLOW},"
        else
          echo "POTENTIALLY VULNERABLE to CVE-2026-80530: affected upstream kernel range and an XFS filesystem with reflink enabled" | sed -${E} "s,.*,${SED_RED_YELLOW},"
        fi
        echo "Exploitation also requires an attacker-writable location and a readable target on the same XFS filesystem"
        echo "Vendor kernels may contain a backported fix; verify the installed kernel package advisory" | sed -${E} "s,.*,${SED_YELLOW},"
      elif [ "$xft80530_reflink_unknown" -gt 0 ]; then
        echo "POTENTIALLY VULNERABLE to CVE-2026-80530: affected upstream kernel range; confirm whether reflink is enabled on the XFS filesystem(s)" | sed -${E} "s,.*,${SED_YELLOW},"
      else
        echo "Mitigated: the mounted XFS filesystem(s) report reflink disabled" | sed -${E} "s,.*,${SED_GREEN},"
      fi
      ;;
    *)
      echo "XFS is mounted, but kernel version could not be assessed for CVE-2026-80530" | sed -${E} "s,.*,${SED_YELLOW},"
      ;;
  esac
  echo ""
}

print_ps(){
  (ls -d /proc/*/ 2>/dev/null | while read f; do
    CMDLINE=$(cat $f/cmdline 2>/dev/null | grep -av "seds,"); #Delete my own sed processess
    if [ "$CMDLINE" ];
      then var USER2=ls -ld $f | awk '{print $3}'; PID=$(echo $f | cut -d "/" -f3);
      printf "  %-13s  %-8s  %s\n" "$USER2" "$PID" "$CMDLINE";
    fi;
  done) 2>/dev/null | sort -r
}

su_brute_user_num(){
  BFUSER=$1
  TRIES=$2
  su_try_pwd "$BFUSER" "" &    #Try without password
  su_try_pwd "$BFUSER" "$BFUSER" & #Try username as password
  su_try_pwd "$BFUSER" "$(echo $BFUSER | rev 2>/dev/null)" & #Try reverse username as password
  if [ "$PASSWORD" ]; then
    su_try_pwd "$BFUSER" "$PASSWORD" & #Try given password
  fi
  for i in $(seq "$TRIES"); do
    su_try_pwd "$BFUSER" "$(echo $top2000pwds | cut -d ' ' -f $i)" & #Try TOP TRIES of passwords (by default 2000)
    sleep 0.007 # To not overload the system
  done
  wait
}

check_if_su_brute(){
  EXISTS_SU="$(command -v su 2>/dev/null || echo -n '')"
  error=$(echo "" | timeout 1 su $(whoami) -c whoami 2>&1);
  if [ "$EXISTS_SU" ] && ! echo $error | grep -q "must be run from a terminal"; then
    echo "1"
  fi
}

get_current_user_privot_pid(){
    CURRENT_USER_PIVOT_PID=""
    if ! [ "$SEARCH_IN_FOLDER" ] && ! [ "$NOUSEPS" ]; then
        # Function to get user by PID
        get_user_by_pid() {
            ps -p "$1" -o user | grep -v "USER"
        }
        # Find processes with PPID and user info, then filter those where PPID's user is different from the process's user
        ps -eo pid,ppid,user | grep -v "PPID" | while read -r pid ppid user; do
            if [ "$ppid" = "0" ]; then
            continue
            fi
            ppid_user=$(get_user_by_pid "$ppid")
            if echo "$user" | grep -Eqv "$ppid_user|root$"; then
            if [ "$ppid_user" = "$USER" ]; then
                CURRENT_USER_PIVOT_PID="$ppid"
            fi
            fi
        done
        echo ""
    fi
}

doas_extract_upstream_version() {
  printf "%s\n" "$1" | grep -oE '[0-9]+(\.[0-9]+){1,2}' | head -n 1
}
doas_version_ge() {
  awk -v left="$1" -v right="$2" 'BEGIN {
    left_n = split(left, left_v, ".")
    right_n = split(right, right_v, ".")
    max_n = left_n > right_n ? left_n : right_n
    for (i = 1; i <= max_n; i++) {
      left_i = (i <= left_n ? left_v[i] : 0) + 0
      right_i = (i <= right_n ? right_v[i] : 0) + 0
      if (left_i > right_i) exit 0
      if (left_i < right_i) exit 1
    }
    exit 0
  }'
}
doas_version_lt() {
  if doas_version_ge "$1" "$2"; then
    return 1
  fi
  return 0
}
doas_version_le() {
  if doas_version_lt "$2" "$1"; then
    return 1
  fi
  return 0
}
doas_read_rules() {
  awk '
    function trim(value) {
      sub(/^[[:space:]]+/, "", value)
      sub(/[[:space:]]+$/, "", value)
      return value
    }
    {
      source = $0
      output = ""
      quoted = 0
      escaped = 0
      for (i = 1; i <= length(source); i++) {
        char = substr(source, i, 1)
        if (char == "#" && !quoted) break
        output = output char
        if (char == "\"" && !escaped) quoted = !quoted
        if (char == "\\" && !escaped) escaped = 1
        else escaped = 0
      }
      output = trim(output)
      if (output ~ /^(permit|deny)([[:space:]]|$)/)
        printf "%d\t%s\n", NR, output
    }
  ' "$1" 2>/dev/null
}
doas_rule_identity() {
  printf "%s\n" "$1" | awk '
    {
      in_setenv = 0
      for (i = 2; i <= NF; i++) {
        token = $i
        if (in_setenv) {
          if (token ~ /}/) in_setenv = 0
          continue
        }
        if (token == "setenv") {
          in_setenv = 1
          continue
        }
        if (token == "nopass" || token == "nolog" || token == "persist" || token == "keepenv")
          continue
        gsub(/^"|"$/, "", token)
        print token
        exit
      }
    }
  '
}
doas_rule_has_option() {
  printf "%s\n" "$1" | awk -v wanted="$2" '
    {
      in_setenv = 0
      for (i = 2; i <= NF; i++) {
        token = $i
        if (in_setenv) {
          if (token ~ /}/) in_setenv = 0
          continue
        }
        if (token == "setenv") {
          if (wanted == token) exit 0
          in_setenv = 1
          continue
        }
        if (token == "nopass" || token == "nolog" || token == "persist" || token == "keepenv") {
          if (wanted == token) exit 0
          continue
        }
        exit 1
      }
      exit 1
    }
  '
}
doas_rule_has_dangerous_environment() {
  if doas_rule_has_option "$1" keepenv; then
    return 0
  fi
  printf "%s\n" "$1" | grep -Eq '(^|[[:space:]{])(setenv[[:space:]]*\{[^}]*[[:space:]])?(PATH|LD_PRELOAD|LD_LIBRARY_PATH|BASH_ENV|ENV|PYTHONPATH|PERL5LIB|RUBYLIB)([=[:space:]}]|$)'
}
doas_rule_command() {
  printf "%s\n" "$1" | awk '
    {
      for (i = 1; i < NF; i++) {
        if ($i == "cmd") {
          command = $(i + 1)
          gsub(/^"|"$/, "", command)
          print command
          exit
        }
      }
    }
  '
}
doas_rule_targets_root() {
  printf "%s\n" "$1" | awk '
    {
      for (i = 1; i < NF; i++) {
        if ($i == "as") {
          target = $(i + 1)
          gsub(/^"|"$/, "", target)
          exit(target == "root" || target == "0" || target == "#0" ? 0 : 1)
        }
      }
      exit 0
    }
  '
}
doas_rule_applies_to_current_user() {
  doas_rule_identity_value="$(doas_rule_identity "$1")"
  case "$doas_rule_identity_value" in
    "$doas_current_user"|"$doas_current_uid"|"#$doas_current_uid") return 0 ;;
  esac
  case "$doas_rule_identity_value" in
    :*)
      doas_rule_identity_value="${doas_rule_identity_value#:}"
      for doas_candidate in $doas_current_groups $doas_current_gids; do
        if [ "$doas_candidate" = "$doas_rule_identity_value" ] || [ "#$doas_candidate" = "$doas_rule_identity_value" ]; then
          return 0
        fi
      done
      ;;
  esac
  return 1
}
doas_command_is_dangerous() {
  doas_rule_cmd="$1"
  doas_rule_cmd="${doas_rule_cmd##*/}"
  case "$doas_rule_cmd" in
    ash|awk|bash|busybox|csh|dash|dstat|ed|env|expect|find|fish|gdb|git|ionice|jrunscript|ksh|less|lua|make|more|mv|nano|nawk|nc|ncat|nice|node|nvim|perl|php|python|python2|python3|rake|rlwrap|ruby|run-parts|rvim|sed|sh|socat|sqlite3|tar|tee|tclsh|vi|vim|watch|xargs|zsh)
      return 0
      ;;
  esac
  if [ -n "${sudoVB1:-}" ] && printf " %s\n" "$1" | grep -Eq "$sudoVB1" 2>/dev/null; then
    return 0
  fi
  if [ -n "${sudoVB2:-}" ] && printf " %s\n" "$1" | grep -Eq "$sudoVB2" 2>/dev/null; then
    return 0
  fi
  return 1
}
doas_get_package_details() {
  doas_package_manager=""
  doas_package_name=""
  doas_package_full_version=""
  doas_package_source=""
  doas_package_homepage=""
  doas_package_implementation="unknown"
  if command -v dpkg-query >/dev/null 2>&1; then
    doas_package_name="$(dpkg-query -S "$1" 2>/dev/null | head -n 1 | sed 's/: .*//' | cut -d: -f1)"
    if [ -n "$doas_package_name" ]; then
      doas_package_manager="dpkg"
      doas_package_full_version="$(dpkg-query -W -f='$''{Version}\n' "$doas_package_name" 2>/dev/null | head -n 1)"
      doas_package_source="$(dpkg-query -W -f='$''{source:Package}\n' "$doas_package_name" 2>/dev/null | head -n 1 | sed 's/^src://')"
      doas_package_homepage="$(dpkg-query -W -f='$''{Homepage}\n' "$doas_package_name" 2>/dev/null | head -n 1)"
    fi
  elif command -v rpm >/dev/null 2>&1; then
    doas_package_line="$(rpm -qf --qf '%{NAME}|%{VERSION}-%{RELEASE}|%{URL}\n' "$1" 2>/dev/null | head -n 1)"
    if [ -n "$doas_package_line" ]; then
      doas_package_manager="rpm"
      doas_package_name="$(printf "%s" "$doas_package_line" | cut -d'|' -f1)"
      doas_package_full_version="$(printf "%s" "$doas_package_line" | cut -d'|' -f2)"
      doas_package_homepage="$(printf "%s" "$doas_package_line" | cut -d'|' -f3-)"
    fi
  elif command -v apk >/dev/null 2>&1; then
    for doas_candidate in opendoas doas; do
      doas_candidate_version="$(apk info -e -v "$doas_candidate" 2>/dev/null | head -n 1)"
      if [ -n "$doas_candidate_version" ]; then
        doas_package_manager="apk"
        doas_package_name="$doas_candidate"
        doas_package_full_version="${doas_candidate_version#${doas_candidate}-}"
        doas_package_homepage="$(apk info -a "$doas_candidate" 2>/dev/null | sed -n 's/^webpage[[:space:]]*:[[:space:]]*//p' | head -n 1)"
        break
      fi
    done
  elif command -v pacman >/dev/null 2>&1; then
    doas_package_line="$(pacman -Qo "$1" 2>/dev/null | head -n 1)"
    doas_package_name="$(printf "%s\n" "$doas_package_line" | sed -nE 's/.* is owned by ([^ ]+) .*/\1/p')"
    doas_package_full_version="$(printf "%s\n" "$doas_package_line" | sed -nE 's/.* is owned by [^ ]+ ([^ ]+).*/\1/p')"
    if [ -n "$doas_package_name" ]; then
      doas_package_manager="pacman"
      doas_package_homepage="$(pacman -Qi "$doas_package_name" 2>/dev/null | sed -n 's/^URL[[:space:]]*:[[:space:]]*//p' | head -n 1)"
    fi
  elif command -v pkg >/dev/null 2>&1; then
    doas_package_name="$(pkg which -q "$1" 2>/dev/null | head -n 1)"
    if [ -n "$doas_package_name" ]; then
      doas_package_manager="pkg"
      doas_package_line="$(pkg query '%n|%v|%o|%w' "$doas_package_name" 2>/dev/null | head -n 1)"
      doas_package_name="$(printf "%s" "$doas_package_line" | cut -d'|' -f1)"
      doas_package_full_version="$(printf "%s" "$doas_package_line" | cut -d'|' -f2)"
      doas_package_source="$(printf "%s" "$doas_package_line" | cut -d'|' -f3)"
      doas_package_homepage="$(printf "%s" "$doas_package_line" | cut -d'|' -f4-)"
    fi
  fi
  doas_homepage_lower="$(printf "%s" "$doas_package_homepage" | tr '[:upper:]' '[:lower:]')"
  case "$doas_homepage_lower:$doas_package_source:$doas_package_name" in
    *duncaen/opendoas*|*:opendoas:*|*:*:opendoas) doas_package_implementation="opendoas" ;;
    *slicer69/doas*) doas_package_implementation="slicer69" ;;
  esac
  if [ "$(uname -s 2>/dev/null)" = "OpenBSD" ]; then
    doas_package_implementation="openbsd"
  fi
}
doas_config_syntax_valid() {
  if [ -n "${TIMEOUT:-}" ]; then
    "$TIMEOUT" 5 "$1" -C "$2" >/dev/null 2>&1
  else
    "$1" -C "$2" >/dev/null 2>&1
  fi
}
doas_check_command() {
  if [ -n "${TIMEOUT:-}" ]; then
    "$TIMEOUT" 5 "$1" -C "$2" "$3" 2>/dev/null
  else
    "$1" -C "$2" "$3" 2>/dev/null
  fi
}

nr48990_fixed_dpkg_version() {
  # Vendor backports from Ubuntu CVE-2024-48990 and Debian DSA-5815-1 /
  # DLA-3957-1; comparing only the upstream 3.8 version would misclassify them.
  case "$1:$2" in
    debian:bullseye|raspbian:bullseye) echo "3.5-4+deb11u4" ;;
    debian:bookworm|raspbian:bookworm) echo "3.6-4+deb12u2" ;;
    debian:trixie|debian:forky|debian:sid) echo "3.7-3.1" ;;
    ubuntu:xenial) echo "2.6-1ubuntu0.1~esm1" ;;
    ubuntu:bionic) echo "3.1-1ubuntu0.1+esm1" ;;
    ubuntu:focal) echo "3.4-6ubuntu0.1+esm1" ;;
    ubuntu:jammy) echo "3.5-5ubuntu2.2" ;;
    ubuntu:noble) echo "3.6-7ubuntu4.3" ;;
    ubuntu:oracular) echo "3.6-8ubuntu4.2" ;;
    ubuntu:plucky) echo "3.6-8ubuntu6" ;;
  esac
}
nr48990_effective_interpscan() {
  nr48990_config="1"
  for nr48990_config_file in "$1"etc/needrestart/needrestart.conf "$1"etc/needrestart/conf.d/*.conf; do
    [ -r "$nr48990_config_file" ] || continue
    nr48990_config_file_value="$(awk '
      /^[[:space:]]*#/ { next }
      {
        nr48990_line = $0
        sub(/[[:space:]]*#.*/, "", nr48990_line)
        if (nr48990_line ~ /^[[:space:]]*[$]nrconf[[:space:]]*\{[[:space:]]*[\047\042]?interpscan[\047\042]?[[:space:]]*\}[[:space:]]*=[[:space:]]*[01][[:space:]]*;/) {
          sub(/^.*=[[:space:]]*/, "", nr48990_line)
          sub(/[[:space:]]*;.*/, "", nr48990_line)
          print nr48990_line
        }
      }
    ' "$nr48990_config_file" 2>/dev/null | tail -n1)"
    [ -n "$nr48990_config_file_value" ] && nr48990_config="$nr48990_config_file_value"
  done
  printf '%s' "$nr48990_config"
}
checkNeedrestartCVE202448990() {
  nr48990_root="${ROOT_FOLDER:-/}"
  case "$nr48990_root" in
    */) ;;
    *) nr48990_root="${nr48990_root}/" ;;
  esac
  nr48990_binary=""
  if [ "$nr48990_root" = "/" ]; then
    nr48990_binary="$(command -v needrestart 2>/dev/null)"
  else
    for nr48990_binary_candidate in usr/sbin/needrestart usr/bin/needrestart sbin/needrestart bin/needrestart; do
      if [ -f "${nr48990_root}${nr48990_binary_candidate}" ]; then
        nr48990_binary="${nr48990_root}${nr48990_binary_candidate}"
        break
      fi
    done
  fi
  nr48990_full_version=""
  nr48990_manager=""
  if command -v dpkg-query >/dev/null 2>&1; then
    nr48990_dpkg_record="$(dpkg-query --admindir="${nr48990_root}var/lib/dpkg" -W -f='$''{Status}|$''{Version}\n' needrestart 2>/dev/null | head -n1)"
    case "$nr48990_dpkg_record" in
      "install ok installed|"*)
        nr48990_full_version="${nr48990_dpkg_record#*|}"
        [ -n "$nr48990_full_version" ] && nr48990_manager="dpkg"
        ;;
    esac
  fi
  if [ -z "$nr48990_full_version" ] && command -v rpm >/dev/null 2>&1; then
    if nr48990_rpm_record="$(rpm --root "$nr48990_root" -q --qf '%{VERSION}-%{RELEASE}\n' needrestart 2>/dev/null)"; then
      nr48990_full_version="$(printf '%s\n' "$nr48990_rpm_record" | head -n1)"
      [ -n "$nr48990_full_version" ] && nr48990_manager="rpm"
    fi
  fi
  [ -n "$nr48990_binary" ] || [ -n "$nr48990_full_version" ] || return 0
  print_3title "Needrestart interpreter-scanner LPE (CVE-2024-48990)" "T1068"
  print_info "https://ubuntu.com/security/CVE-2024-48990"
  nr48990_os_release="${nr48990_root}etc/os-release"
  nr48990_distro_id="$(sed -nE 's/^ID="?([^" ]+)"?$/\1/p' "$nr48990_os_release" 2>/dev/null | head -n1)"
  nr48990_codename="$(sed -nE 's/^VERSION_CODENAME="?([^" ]+)"?$/\1/p' "$nr48990_os_release" 2>/dev/null | head -n1)"
  nr48990_ubuntu_codename="$(sed -nE 's/^UBUNTU_CODENAME="?([^" ]+)"?$/\1/p' "$nr48990_os_release" 2>/dev/null | head -n1)"
  if [ -n "$nr48990_ubuntu_codename" ]; then
    nr48990_distro_id="ubuntu"
    nr48990_codename="$nr48990_ubuntu_codename"
  fi
  nr48990_upstream_version="$(lp_extract_upstream_version "$nr48990_full_version")"
  nr48990_interpscan="$(nr48990_effective_interpscan "$nr48990_root")"
  nr48990_dpkg_fixed=""
  nr48990_status="unknown"
  if [ "$nr48990_manager" = "dpkg" ] && command -v dpkg >/dev/null 2>&1; then
    nr48990_dpkg_fixed="$(nr48990_fixed_dpkg_version "$nr48990_distro_id" "$nr48990_codename")"
    if [ -n "$nr48990_dpkg_fixed" ]; then
      if dpkg --compare-versions "$nr48990_full_version" lt "$nr48990_dpkg_fixed"; then
        nr48990_status="affected"
      else
        nr48990_status="fixed"
      fi
    fi
  fi
  if [ "$nr48990_status" = "unknown" ] && [ -n "$nr48990_upstream_version" ]; then
    if lp_version_lt "$nr48990_upstream_version" "3.8"; then
      nr48990_status="potential"
    else
      nr48990_status="fixed"
    fi
  fi
  echo "needrestart package: ${nr48990_full_version:-version unknown}${nr48990_manager:+ ($nr48990_manager)}" | sed -${E} "s,.*,${SED_LIGHT_CYAN},"
  if [ -n "$nr48990_dpkg_fixed" ]; then
    echo "Vendor fixed version for ${nr48990_distro_id:-unknown} ${nr48990_codename:-unknown}: $nr48990_dpkg_fixed"
  fi
  case "$nr48990_status:$nr48990_interpscan" in
    affected:0|potential:0)
      echo "Affected needrestart version detected, but the official interpscan=0 mitigation is active; update is still recommended" | sed -${E} "s,.*,${SED_YELLOW},"
      ;;
    affected:*)
      echo "VULNERABLE to CVE-2024-48990: needrestart $nr48990_full_version is below the vendor fixed version and interpreter scanning is enabled" | sed -${E} "s,.*,${SED_RED_YELLOW},"
      ;;
    potential:*)
      echo "Potentially vulnerable to CVE-2024-48990: upstream needrestart $nr48990_upstream_version is before 3.8 and interpreter scanning is enabled; verify distro backports" | sed -${E} "s,.*,${SED_RED_YELLOW},"
      ;;
    fixed:*)
      echo "needrestart $nr48990_full_version is not vulnerable to CVE-2024-48990 according to the known vendor/upstream fixed version" | sed -${E} "s,.*,${SED_GREEN},"
      ;;
    unknown:0)
      echo "needrestart is present; version is unknown, but the interpscan=0 mitigation is active" | sed -${E} "s,.*,${SED_YELLOW},"
      ;;
    *)
      echo "needrestart is present with interpreter scanning enabled, but its version could not be assessed" | sed -${E} "s,.*,${SED_RED_YELLOW},"
      ;;
  esac
  echo "Effective interpreter scanning: $nr48990_interpscan (0=disabled mitigation, 1=enabled/default)"
  echo ""
}

