if check_mitre_filter "T1555.001"; then
if [ "$MACPEAS" ];then
  print_2title "SystemKey" "T1555.001"
  echo "The SystemKey is used by FileVault to encrypt/decrypt the volume. If you can read it, you might be able to decrypt the disk."
